       WHERE hierarchy_scope_id IS NULL AND equipment_id IN
       ('DSP-01','GRN-01','FBD-01','BLN-01','TPR-01','COT-01','BLS-01','CRT-01','WH-QUAR','WH-REL','WH-REJ',
        'SITE-PH-01','AREA-SOLID','AREA-PACK');
